def style_chart_area(chart, has_legend=True):
    """Apply dark-theme styling to chart."""
    chart.chart_style = 2
    plot = chart.plots[0]
    # Transparent chart area
    chart.element.find(qn('c:chartSpace')).find(qn('c:chart')).find(qn('c:plotArea'))
    try:
        chart.font.color.rgb = TEXT_MUTED
        chart.font.name = "Calibri"
        chart.font.size = Pt(10)
    except:
        pass
    if has_legend and chart.has_legend:
        chart.legend.include_in_layout = False
        try:
            chart.legend.font.color.rgb = TEXT_MUTED
            chart.legend.font.size = Pt(10)
        except:
            pass

